package com.golfhomes.society.controller; import com.golfhomes.society.model.*; import com.golfhomes.society.repository.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/voting") @CrossOrigin(origins="http://localhost:5173") public class PollController { final PollRepository polls; final VoteRepository votes; PollController(PollRepository p,VoteRepository v){polls=p;votes=v;} @GetMapping List<Poll> all(){return polls.findAll();} @PostMapping Poll create(@RequestBody Poll p){p.setStatus("PLANNED");return polls.save(p);} @PostMapping("/{id}/extend") Poll extend(@PathVariable Long id,@RequestParam String newEnd){Poll p=polls.findById(id).orElseThrow();p.setEndAt(LocalDateTime.parse(newEnd));return polls.save(p);} @PostMapping("/{id}/vote") Vote vote(@PathVariable Long id,@RequestBody Vote v){if(votes.findAll().stream().anyMatch(x->x.getPollId().equals(id)&&x.getFlatNumber().equals(v.getFlatNumber())))throw new IllegalStateException("This flat has already voted");v.setPollId(id);v.setVotedAt(LocalDateTime.now());return votes.save(v);} }
